package com._8x8.herd.device_logs.upload.web;

import com._8x8.herd.device_logs.upload.policy.Rejection;

import org.springframework.http.HttpStatus;

/**
 * The one place that turns a {@link Rejection} into an HTTP status (ADR 0009). The switch has no default, so a new
 * reason does not compile until it has a code here. Never 503.
 */
final class RejectionStatusMapper {

    private RejectionStatusMapper() {
    }

    static HttpStatus status(Rejection rejection) {
        return switch (rejection) {
            case BAD_FILE_NAME -> HttpStatus.BAD_REQUEST;
            case FILE_TYPE_DISABLED, UNTRUSTED_IDENTITY, MAC_MISMATCH -> HttpStatus.FORBIDDEN;
            case LENGTH_REQUIRED -> HttpStatus.LENGTH_REQUIRED;
            case TOO_LARGE -> HttpStatus.PAYLOAD_TOO_LARGE;
            // Tomcat has already sent these itself, from InputBuffer.handleReadException, when its read of the body
            // failed. Mapping them to the same codes keeps the log line and what the phone got in step.
            case BODY_INCOMPLETE -> HttpStatus.BAD_REQUEST;
            case BODY_TIMEOUT -> HttpStatus.REQUEST_TIMEOUT;
            // Phones don't retry on 429, and nothing is lost: app.log carries its lines into the next upload, and the
            // other files are full copies every time. That next upload gets a new key from its own receive time.
            case KEY_EXISTS, STORAGE_FAILED -> HttpStatus.TOO_MANY_REQUESTS;
        };
    }
}
